import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷天大壮","description":"周易折中 - 雷天大壮","frontmatter":{"title":"雷天大壮","description":"周易折中 - 雷天大壮"},"headers":[],"relativePath":"zh/classics/zhezhong/040.md","filePath":"zh/classics/zhezhong/040.md"}'),h={name:"zh/classics/zhezhong/040.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="雷天大壮" tabindex="-1">雷天大壮 <a class="header-anchor" href="#雷天大壮" aria-label="Permalink to “雷天大壮”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>大壮序卦曰：遁者，退也。物不可以终遁，故受之以大壮。遁为违去之义，壮为进盛之义。遁者，阴长而阳遁也。大壮，阳之壮盛也。衰则必盛，消息相须，故既遁则必壮。大壮所以次遁也。为卦震上干下，乾刚而震动，以刚而动，大壮之义也。刚阳大也，阳长已过中矣，大者壮盛也。又雷之威震而在天上，亦大壮之义也。</p><p>大壮：利贞</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>大，谓阳也。四阳盛长，故为大壮，二月之卦也。阳壮则占者吉亨，不假言，但利在正固而已。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>《大壮》之道利于贞正也，《大壮》而不得其正，强猛之为耳，非君子之道壮盛也。</p><p>注意：原文没有标点符号，此处AI解读认为并不通顺，所以给出以下解读，可做参考。</p><p>《大壮》之道，利于贞正也。《大壮》而不得其正，强猛之为耳，非君子之道。壮盛也，应依正理而行，方可显其利。</p><p>象曰：雷在天上，大壮；君子以非礼弗履</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>自胜者强</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>雷震于天上，大而壮也。君子观大壮之象，以行其壮。君子之大壮者，莫若克己复礼。古人云：“自胜之谓强。”中庸于和而不流，中立而不倚，皆曰“强哉矫”。赴汤火，蹈白刃，武夫之勇可能也；至于克己复礼，则非君子之大壮，不可能也。故云“君子以非礼弗履”。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰：克己反礼，壮莫盛焉。</p></li><li><p>朱子语类云：雷在天上，是甚生威严。人之克己，须是如雷在天上，方能克去非礼。</p></li><li><p>项氏安世曰：君子所以养其刚大者，亦曰“非礼勿履”而已。</p></li></ul><p>彖曰：大壮，大者壮也。刚以动，故壮</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>释卦名义，以卦体言，则阳长过中，大者壮也。以卦徳言，则乾刚震动，所以壮也。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>所以名大壮者，谓大者壮也。阴为小，阳为大，阳长以盛，是大者壮也。下刚而上动，以干之，至刚而动，故为大壮，为大者壮与壮之大也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li>项氏安世曰：刚则不为物欲所桡，故其动也壮。使以血气而动，安得壮乎？</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>大者谓阳也，大者壮谓四阳盛长也。此句正释名卦之义。刚以动故壮，一句非正释卦名，乃推明卦之善以起辞义耳。凡曰“故”者，皆同义，如“顺以说，故聚”，“明以动，故丰”是也。</p><p>大壮，利贞。大者正也，正大而天地之情可见矣</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>释“利贞”之义而极言之。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>大者既壮，则利于贞正。正而大者，道也。极正大之理，则天地之情可见矣。天地之道，常久而不已者，至大至正也。正大之理，学者黙识心通可也。不云“大正”而云“正大”，恐疑为一事也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类问 ：如何见天地之情？曰：正大便见得天地之情。天地只是正大，未尝有些子邪处。</p></li><li><p>胡氏炳文曰 ：心未易见，故疑其辞曰“复其见天地之心乎？”情则可见矣，故直书之。孟子养气之论，自此而出。大者壮也，即是其为气也至大至刚；大者正也，即是以直养而无害。</p></li></ul><p>初九：壮于趾，征凶，有孚</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>趾在下而进动之物也。刚阳处下而当壮时，壮于进者也，故有此象。居下而壮于进，其凶必矣，故其占又如此。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>初阳刚干体而处下，壮于进者也。在下而用壮，壮于趾也。趾在下而进力之物，九在下用壮而不得其中。夫以刚处壮，虽居上犹不可行，况在下乎？故征则其凶。有孚，孚信也，谓以壮往则得凶可必也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：在下而壮，故曰“壮于趾”也。居下而用刚壮，以斯而进，穷凶可必也。故曰“征凶有孚”。</p></li><li><p>王氏申子曰：卦虽以刚壮为义，然爻义皆贵于用柔。盖以刚而动刚，不可过也。趾在下而主于行，初干体而居刚用刚，是壮于行而不顾者也。在上犹为过，况在下乎？其凶必矣。</p></li></ul><p>象曰：壮于趾，其孚穷也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>言必穷困</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>在最下而用壮以行，可必信其穷困而凶也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰：居下而用壮，任刚而决行，信乎其穷而凶也。</li></ul><p>九二：贞吉</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>以阳居阴，已不得其正矣。然所处得中，则犹可因以不失其正，故戒占者使因中以求正，然后可以得吉也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二虽以阳刚当大壮之时，然居柔而处中，是刚柔得中，不过于壮，得贞正而吉也。或曰：“贞非以九居二为戒乎？”曰：“易取所胜为义，以阳刚健体当大壮之时，处得中道，无不正也。”在四则有不正之戒，人能识时义之轻重，则可以学易矣。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：居得中位，以阳居阴，履谦不亢，是以贞吉。</p></li><li><p>易氏祓曰：爻贵得位，大壮则以阳居阴为吉。盖虑其阳刚之过于壮也，故二与四皆言贞吉。</p></li></ul><p>象曰：九二贞吉，以中也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>所以贞正而吉者，以其得中道也。中则不失正，况阳刚而干礼乎？</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖达曰：以其居中履谦，行不违礼，故得正而吉也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>卦言大壮利贞，惟九二刚徳则为大壮，体则为壮，而居中则为处壮之贞，乃卦之主也。故传言以中明大壮之贞在于中也。</p><p>九三：小人用壮，君子用罔，贞厉。羝羊触藩，羸其角</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>过刚不中，当壮之时，是小人用壮，而君子则用罔也。罔，无也，视有如无。君子之过于勇者也，如此则虽正亦危矣。羝羊，刚壮喜触之物；藩篱也；羸，困也。贞厉之占，其象如此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>九三以刚居阳而处壮，又当干体之终，壮之极者也。极壮如此，在小人则为用壮，在君子则为用罔。小人尚力，故用其壮勇；君子志刚，故用罔。罔，无也，犹云蔑也，以其至刚，蔑视于事而无所忌惮也。君子小人以地言，如君子有勇而无义为乱。刚柔得中，则不折不屈，施于天下而无不宜；苟刚之太过，则无和顺之德，多伤莫与。贞固守此，则危道也。凡物莫不用其壮，齿者啮，角者触，蹄者踶；羊壮于首，羝为喜触，故取为象。羊喜触藩篱，以藩篱当其前也，盖所当必触。喜用壮如此，必羸困其角矣，犹人尚刚壮，所当必用，必至摧困也。三壮甚如此，而不至凶，何也？曰：如三之为其往，足以致凶，而方言其危，故未及于凶也。凡可以致凶而未至者，则曰厉也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>京氏房曰：壮一也，小人用之，君子有而不用。</p></li><li><p>刘氏牧曰：罔，不也。君子尚德而不用壮，若固其壮则危矣。</p></li><li><p>胡氏瑗曰：九三处下卦之上，当乾健之极，以阳居阳，是强壮之人也。以小人乘此，则必恃刚强陵犯于人，虽至壮极而不已，是用壮者也。君子则不然，虽壮而不矜，虽大而不伐，罔而不用其壮也。小人居强壮之时，动则过中，进则不顾，是犹刚狠之羊，虽藩在前，亦触突而进，以至反羸其角，凶之道也。</p></li><li><p>郭氏雍曰：刚至三而壮矣。小人务胜人，故喜壮而用之；君子务胜己之私，是以勿用壮于外也。以用壮为正，则危矣。羊狠喜触，用壮之象也。触藩羸角，用壮而厉也。君子用罔者，君子罔以壮为用也。先儒或为罗网之罔，失之矣。</p></li><li><p>项氏安世曰：既曰“小人用壮”，又曰“君子用罔”，劝戒备矣。又曰“贞厉，羝羊触藩，羸其角”者，恐人以用刚居刚为得正也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>京氏以下诸家说“用罔”与传义异，以夫子小象文意参之，诸说近是。</p><p>象曰：小人用壮，君子罔也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>小人以壮败，君子以罔困</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>在小人则为用其强壮之力，在君子则为用罔（无）。志气刚强，蔑视于事，靡所顾惮也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰：君子用罔，说者不同。然观爻辞之例，如“小人吉，大人否”、“亨，君子吉，小人否”、“妇人吉，夫子凶”，皆是相反之辞。又象辞曰“小人用壮，君子罔也”，全与“君子好遁，小人否也”句法相类。诗书中“罔”字与“弗”字、“勿”字、“毋”字通用，皆禁止之义也。</p></li><li><p>杨氏简曰：九三益进，势虽壮，君子之心未尝以为意焉。唯小人则自喜己势之壮而益肆益壮，是谓“小人用壮”。罔无也，言君子之所用异乎小人之用也，故曰“小人用壮，君子罔也”。</p></li><li><p>龚氏焕曰：大壮本以四阳盛长而得名，九三又以阳居阳而过刚，壮而又壮者也。用壮如此，是小人之所为，而非君子之道，故曰“君子用罔”。象释之曰“小人用壮，君子罔也”，语意与遁九四“君子好遁，小人否也”同。盖遁之九四即大壮九三之反对，皆君子小人并言。</p></li><li><p>俞氏琰曰：孔子恐后世疑爻辞有两“用”字，以为小人之用与君子同，故特去其一。</p></li></ul><p>九四：贞吉悔亡，藩决不羸，壮于大舆之輹</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>贞吉悔亡，与咸九四同占。藩决不羸，承上文而言也。决，开也。三前有四，犹有藩焉；四前二阴，则藩决矣。壮于大舆之輹，亦可进之象也。以阳居阴，不极其刚，故其象占如此。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四阳刚长，盛壮已过中，壮之甚也。然居四为不正方，君子道长之时，岂可有不正也？故戒以贞则吉而悔亡。盖方道长之时，小失则害亨进之势，是有悔也。若在他卦，重刚而居柔，未必不为善也，大过是也。藩所以限隔也，藩篱决开，不复羸困其壮也。髙大之车轮輹，强壮其行之利可知，故云“壮于大舆之輹”。輹，轮之要处也，车之败常在折輹，輹壮则车强矣。云“壮于輹”，谓壮于进也。輹与辐同。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：未有违谦越礼而能全其壮者也。故阳爻皆以居阴位为美。</p></li><li><p>郑氏汝谐曰：居四阳之终，其壮易过，故必正吉则悔亡。群阳并进，非二阴之所能止，藩决不羸，其道通也。壮于大舆之輹，其行健也。</p></li><li><p>朱子语类云：九二贞吉只是自守而不进，九四却是有可进之象。盖以阳居阴，不极其刚，而前遇二阴，有藩决之象，所以为进，非如九二前有三四二阳隔之不得进也。</p></li><li><p>俞氏琰曰：爻刚位柔，不极其壮，故因占设戒曰“贞吉悔亡”。三以九四之刚在前，如藩篱之障而不能进，故触而受羸；四以六五之柔在前，如藩篱剖破而无俟乎触，故不羸。曰“藩决不羸”，而不及羊，承九三之辞也。</p></li></ul><p>象曰：藩决不羸，尚往也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>刚阳之长必至于极，四虽已盛，然其往未止也。以至盛之阳用壮而进，故莫有当之。藩决开而不羸困其力也，尚往其进不已也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>项氏安世曰：九四以刚居柔，有能正之吉，无过刚之悔。“贞吉悔亡”四字既尽之矣。又曰“藩决不羸”，壮于大舆之輹者，恐人以居柔为不进也，故以“尚往”明之。</li></ul><p>六五：丧羊于易，无悔</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>卦体似兑，有羊象焉。外柔而内刚者也，独六五以柔居中，不能抵触，虽失其壮，然亦无所悔矣。故其象占如此。易，容易之易，言忽然不觉其亡也；或作疆埸之埸，亦通（汉食货志“埸”作“易”）。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>羊群行而喜触，以象诸阳并进。四阳方长而并进，五以柔居上，若以力制则难胜而有悔，惟和易以待之，则群阳无所用其刚，是丧其壮于和易也。如此则可以无悔。五以位言则正，以德言则中，故能用和易之道，使群阳虽壮无所用也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云：“丧羊于易”不若作“疆埸之易”（汉食货志“疆埸”之“埸”正作“易”）。盖后面有“丧牛于易”，亦同此义。今《本义》所注只是从前所说如此，只且仍旧耳。</p></li><li><p>胡氏炳文曰：旅上九“丧牛于易”，牛性顺，上九以刚居极，不觉失其所谓顺；此曰“丧羊于易”，羊性刚，六五以柔居中，不觉失其所谓刚，自失其壮，故爻独不言壮。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>壮之道贵乎得中。九二方壮之时，以刚处中，壮之正也；至六五，则壮已过矣，又以柔处中，则无所用其壮矣。故虽丧羊而无悔。</p><p>象曰：丧羊于易，位不当也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>所以必用柔和者，以阴柔居尊位故也。若以阳刚中正得尊位，则下无壮矣。以六五位不当也，故设“丧羊于易”之义。然大率治壮不可用刚，夫君臣上下之势不相侔也。苟君之权足以制乎下，则虽有强壮跋扈之人，不足谓之壮也。必人君之势有所不足，然后谓之治壮。故治壮之道不可以刚也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏安石曰：刚柔者所以立本，变通者所以趋时。方其趋时，则位正当而有咎凶，位不当而无悔者有矣。大壮之时，得中而处之以柔，能丧其很者也。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>位当位不当，易例多借爻位以发明其德与时地之相当不相当也。此位不当，不止谓以阴居阳不任刚壮而已，盖谓四阳已过矣，则五所处非当壮之位也。于是而以柔中居之，故为“丧羊于易”。</p><p>上六：羝羊触藩，不能退，不能遂，无攸利，艰则吉</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>壮终动极，故触藩而不能退，然其质本柔，故又不能遂其进也。其象如此，其占可知。然犹幸其不刚，故能艰以处，则尚可以得吉也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>羝羊但取其用壮，故阴爻亦称之。六以阴处震终而当壮，极其过可知，如羝羊之触藩篱，进则碍身，退则妨角，进退皆不可也。才本阴柔，故不能胜已以就义，是不能退也。阴柔之人，虽极用壮之心，然必不能终其壮，有摧必缩，是不能遂也。其所为如此，无所往而利也。阴柔处壮，不能固其守，若遇艰困，必失其壮，失其壮则反得柔弱之分矣。是艰则得吉也。用壮则不利，知艰而处柔则吉也。居壮之终，有变之义也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云：上六取喻甚巧，盖壮终动极，无可去处，如羝羊之角挂于藩上，不能退遂。然“艰则吉”者，毕竟有可进之理，但必艰始吉耳。</p></li><li><p>易氏祓曰：三前有四，故为触藩；四前遇阴，故为藩决。上六前无滞碍，而亦言触藩者，处一卦之穷也。不能退者，在众爻之上；不能遂者，亢而不可前进也。然能艰则吉，此《易》之所以备劝戒也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>五与上皆阴爻而当阳壮已过之时，五犹曰“丧羊”，而上反曰“羝羊触藩”，何也？盖《易》者，像也。羊之触也，以角。卦似兑，有羊象，而上六适当角位，故虽阴爻而亦云触藩也。阴柔不至于羸角，但不能退、不能遂而已。艰则吉者，知其难而不敢轻易以处之也，故可进则进，不可进则退。杂卦谓“大壮则止”，是也。</p><p>象曰：不能退，不能遂，不详也；艰则吉，咎不长也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>非其处而处，故进退不能，是其自处之不详慎也。艰则吉，柔遇艰难，又居壮终，自当变矣。变则得其分，过咎不长，乃吉也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰：临卦六三与大壮上六皆言“无攸利”，皆曰“咎不长”。盖六三之忧与上六之艰，不贵无过，而贵改过也。</p></li><li><p>俞氏琰曰：人之处事，以为易则不详审，以为艰则详审。向也既以不详审而致咎，今详审而不轻率，则其咎不长也。</p></li></ul><p>总论</p><p>项氏安世曰：有以事理得中为正者，有以阴阳当位为正者。刚以柔济之，柔以刚济之，使不失其正，此事理之正也。以刚处刚，以柔处柔，各当其位，此爻位之正也。大壮之时义，其所谓“利贞”者，利守事理之正，不以爻位言也。是故九二、九四、六五三爻不当位而皆利，初九、九三、上六三爻当位而皆不利。又于九二、九四爻辞明言“贞吉”，于初九、九三爻辞明言“征凶”、“贞厉”，圣人犹恐其未明也，又以小象释之。于九二则曰“九二贞吉，以中也”，明正吉以中而不以位也；于六五则曰“位不当也”，亦明无悔在中不在位也。《易》之时义屡迁，如此。</p>',121)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
